-- GoliathApp portal navigation shell (NavTree, entitlements, Meta object bridge).
-- Copied from GoliathOmics workflow_engine/sql_pg/portal_clinical_schema.sql (shell tables only).

CREATE SCHEMA IF NOT EXISTS portal;

CREATE TABLE IF NOT EXISTS portal."NodeInfos" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Name" varchar(128) NOT NULL,
  "Singleton" boolean NOT NULL DEFAULT true,
  "TypeId" smallint NULL DEFAULT 1,
  "FrameKey" varchar(100) NULL,
  CONSTRAINT "PK_portal_NodeInfos" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS portal."NavTree" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ParentID" integer NULL,
  "Caption" varchar(50) NOT NULL,
  "Seq" smallint NOT NULL,
  "InfoID" integer NULL,
  "NodePath" varchar(2048) NULL,
  "SortPath" varchar(2048) NULL,
  CONSTRAINT "PK_portal_NavTree" PRIMARY KEY ("ID")
);

CREATE TABLE IF NOT EXISTS portal."Role2Node" (
  "RoleId" integer NOT NULL,
  "NodeId" integer NOT NULL,
  "ScopeId" integer NOT NULL,
  CONSTRAINT "PK_portal_Role2Node" PRIMARY KEY ("ScopeId", "RoleId", "NodeId")
);

CREATE TABLE IF NOT EXISTS portal."UserRoles" (
  "UserId" bigint NOT NULL,
  "RoleId" integer NOT NULL,
  CONSTRAINT "PK_portal_UserRoles" PRIMARY KEY ("UserId", "RoleId")
);

DO $migrate$
BEGIN
  IF to_regclass('e_portal."UserRoles"') IS NOT NULL THEN
    EXECUTE $ins$
      INSERT INTO portal."UserRoles" ("UserId", "RoleId")
      SELECT ur."UserId", ur."RoleId"
      FROM e_portal."UserRoles" ur
      ON CONFLICT ("UserId", "RoleId") DO NOTHING
    $ins$;
  END IF;
END
$migrate$;

CREATE TABLE IF NOT EXISTS portal."Objs" (
  "ObjID" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "MetaObjID" integer NOT NULL,
  CONSTRAINT "PK_portal_Objs" PRIMARY KEY ("ObjID", "MetaObjID")
);

CREATE OR REPLACE VIEW portal."viewUserAllRoles" AS
SELECT ur."UserId" AS "UserId", ur."RoleId" AS "RoleId"
FROM portal."UserRoles" ur;

-- Register a navigation node (apps extend the shared NavTree / NodeInfos tables).
CREATE OR REPLACE FUNCTION portal.sp_nav_register_node(
  p_parent_id integer,
  p_caption text,
  p_seq smallint,
  p_info_id integer DEFAULT NULL,
  p_node_path text DEFAULT NULL,
  p_sort_path text DEFAULT NULL,
  OUT node_id integer
)
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_caption IS NULL OR btrim(p_caption) = '' THEN
    RAISE EXCEPTION 'caption is required';
  END IF;
  IF p_seq IS NULL THEN
    RAISE EXCEPTION 'seq is required';
  END IF;

  INSERT INTO portal."NavTree" (
    "ParentID", "Caption", "Seq", "InfoID", "NodePath", "SortPath"
  )
  VALUES (
    p_parent_id, p_caption, p_seq, p_info_id, p_node_path, p_sort_path
  )
  RETURNING "ID" INTO node_id;
END;
$$;
